import re
from functools import cache

from .errors import ValidationError
from .money import convert_money, parse_money, parse_rate
from .splits import split_equal, split_exact, split_percent, split_shares


def load_group(data):
    """Validate a group and calculate each expense's shares."""
    if not isinstance(data, dict):
        raise ValidationError("group must be an object")
    currency = _currency_code(data.get("currency"))
    raw_members = data.get("members")
    if not isinstance(raw_members, list) or not raw_members:
        raise ValidationError("members must be a non-empty list")
    members = {}
    for value in raw_members:
        name = _name(value)
        key = name.casefold()
        if key in members:
            raise ValidationError(f"duplicate name {name!r}")
        members[key] = name
    raw_expenses = data.get("expenses")
    if not isinstance(raw_expenses, list):
        raise ValidationError("expenses must be a list")

    rates = None

    @cache
    def rate_for(code):
        nonlocal rates
        if rates is None:
            rates = _rate_entries(data.get("rates", {}))
        if code not in rates:
            raise ValidationError(f"missing exchange rate for {code}")
        return parse_rate(rates[code], code)

    expenses = []
    seen_ids = set()
    for index, expense in enumerate(raw_expenses, start=1):
        if not isinstance(expense, dict):
            raise ValidationError(f"expense #{index} must be an object")
        expense_id = expense.get("id")
        if not isinstance(expense_id, str):
            raise ValidationError(f"expense #{index} id must be a string")
        if expense_id in seen_ids:
            raise ValidationError(f"duplicate expense id '{expense_id}'")
        seen_ids.add(expense_id)

        try:
            expenses.append(_load_expense(expense, members, currency, rate_for))
        except ValidationError as error:
            raise ValidationError(f"expense '{expense_id}': {error}") from error

    # Rates are only needed for groups with foreign expenses. Check the entries
    # used by expenses first so a bad rate can be reported with its expense ID.
    if rates is not None:
        for code in rates:
            rate_for(code)
    return list(members.values()), expenses


def _currency_code(value, field="currency"):
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z]{3}", value):
        raise ValidationError(f"{field} must be a three-letter code")
    return value.upper()


def _rate_entries(raw_rates):
    if not isinstance(raw_rates, dict):
        raise ValidationError("rates must be an object")
    rates = {}
    for key, value in raw_rates.items():
        code = _currency_code(key, "rate currency")
        if code in rates:
            raise ValidationError(f"duplicate exchange rate for {code}")
        rates[code] = value
    return rates


def _name(value):
    if isinstance(value, str):
        name = value.strip()
        if name:
            return name.lower()
    raise ValidationError("member names must be non-empty strings")


def _resolve_name(value, members, role):
    name = _name(value)
    member = members.get(name.casefold())
    if member is None:
        raise ValidationError(f"unknown {role} {name!r}")
    return member


def _participants(values, members):
    names = []
    seen = set()
    for value in values:
        name = _resolve_name(value, members, "participant")
        if name in seen:
            raise ValidationError(f"duplicate name {name!r}")
        seen.add(name)
        names.append(name)
    return names


def _load_expense(expense, members, group_currency, rate_for):
    payer = _resolve_name(expense.get("payer"), members, "payer")
    amount = parse_money(expense.get("amount"))
    if amount == 0:
        raise ValidationError("expense amount must be greater than zero")

    split = expense.get("split")
    if not isinstance(split, dict):
        raise ValidationError("split must be an object")
    kind = split.get("type")
    if not isinstance(kind, str):
        raise ValidationError("split type must be a string")

    currency = _currency_code(expense.get("currency", group_currency))
    if currency != group_currency:
        if kind == "exact":
            raise ValidationError("exact splits are only allowed in the group currency")
        amount = convert_money(amount, rate_for(currency))

    if kind == "equal":
        among = members.values()
        if "among" in split:
            raw_among = split["among"]
            if not isinstance(raw_among, list) or not raw_among:
                raise ValidationError("among must be a non-empty list")
            among = _participants(raw_among, members)
        shares = split_equal(amount, among)
    elif kind == "exact":
        shares = split_exact(amount, _split_values(split, "amounts", members))
    elif kind == "percent":
        shares = split_percent(amount, _split_values(split, "percents", members))
    elif kind == "shares":
        shares = split_shares(amount, _split_values(split, "shares", members))
    else:
        raise ValidationError(f"unknown split type {kind!r}")
    return payer, amount, shares


def _split_values(split, field, members):
    values = split.get(field)
    if not isinstance(values, dict):
        raise ValidationError(f"{field} must be an object")
    names = _participants(values, members)
    return dict(zip(names, values.values()))
import re

from .errors import ValidationError


_DECIMAL = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_RATE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
# Convert long numbers in chunks to stay below Python's integer string limit.
_CHUNK_DIGITS = 500
_CHUNK_BASE = 10**_CHUNK_DIGITS


def parse_integer(value):
    """Read an already syntax-checked integer of any length."""
    digits = value.removeprefix("-")
    integer = 0
    end = len(digits) % _CHUNK_DIGITS
    if end:
        integer = int(digits[:end])
    for start in range(end, len(digits), _CHUNK_DIGITS):
        integer = integer * _CHUNK_BASE + int(digits[start : start + _CHUNK_DIGITS])
    return -integer if value.startswith("-") else integer


def parse_money(value, *, field="amount"):
    """Read an unsigned decimal string as integer hundredths."""
    if not isinstance(value, str) or not _DECIMAL.fullmatch(value):
        raise ValidationError(f"{field} must be a decimal string with at most two fractional digits")

    whole, _, fraction = value.partition(".")
    return parse_integer(whole) * 100 + int(fraction.ljust(2, "0"))


def parse_rate(value, currency):
    if not isinstance(value, str) or not _RATE.fullmatch(value):
        raise ValidationError(f"rate for {currency} must be a positive decimal string")
    whole, _, fraction = value.partition(".")
    numerator = parse_integer(whole + fraction)
    if numerator == 0:
        raise ValidationError(f"rate for {currency} must be greater than zero")
    return numerator, 10 ** len(fraction)


def convert_money(amount, rate):
    """Convert cents using an exact ratio and round to the nearest even cent on ties."""
    numerator, denominator = rate
    cents, remainder = divmod(amount * numerator, denominator)
    twice_remainder = remainder * 2
    if twice_remainder > denominator or (twice_remainder == denominator and cents % 2):
        cents += 1
    return cents


def format_money(cents, *, signed=False):
    whole, fraction = divmod(abs(cents), 100)
    chunks = []
    while whole >= _CHUNK_BASE:
        whole, chunk = divmod(whole, _CHUNK_BASE)
        chunks.append(f"{chunk:0{_CHUNK_DIGITS}d}")
    digits = str(whole) + "".join(reversed(chunks))

    sign = ""
    if cents < 0:
        sign = "-"
    elif signed and cents > 0:
        sign = "+"
    return f"{sign}{digits}.{fraction:02d}"
from .errors import ValidationError
from .money import parse_money


def split_equal(amount, among):
    return _apportion(amount, dict.fromkeys(among, 1), len(among))


def split_exact(amount, amounts):
    shares = {name: parse_money(value) for name, value in amounts.items()}
    if sum(shares.values()) != amount:
        raise ValidationError("exact shares must add up to the expense amount")
    return shares


def split_percent(amount, percents):
    weights = {name: parse_money(value, field="percentage") for name, value in percents.items()}
    if any(weight == 0 for weight in weights.values()):
        raise ValidationError("percentages must be greater than zero")
    if sum(weights.values()) != 10_000:
        raise ValidationError("percentages must add up to 100")
    return _apportion(amount, weights, 10_000)


def split_shares(amount, weights):
    if not weights:
        raise ValidationError("shares must include at least one participant")
    if any(type(weight) is not int or weight <= 0 for weight in weights.values()):
        raise ValidationError("share counts must be positive integers")
    return _apportion(amount, weights, sum(weights.values()))


def _apportion(amount, weights, denominator):
    shares = {}
    remainders = []
    for name, weight in weights.items():
        shares[name], remainder = divmod(amount * weight, denominator)
        remainders.append((-remainder, name))

    leftover = amount - sum(shares.values())
    for _, name in sorted(remainders)[:leftover]:
        shares[name] += 1
    return shares
from heapq import heapify, heappop, heappush

from .model import load_group


def balances(group):
    members, expenses = load_group(group)
    result = dict.fromkeys(members, 0)
    for payer, amount, shares in expenses:
        result[payer] += amount
        for name, owed in shares.items():
            result[name] -= owed
    return result


def settle(group):
    net = balances(group)
    # Negative amounts rank the largest debt or credit first in each heap.
    debtors = [(cents, name) for name, cents in net.items() if cents < 0]
    creditors = [(-cents, name) for name, cents in net.items() if cents > 0]
    heapify(debtors)
    heapify(creditors)

    transfers = []
    while debtors:
        debt, debtor = heappop(debtors)
        credit, creditor = heappop(creditors)
        payment = min(-debt, -credit)
        transfers.append((debtor, creditor, payment))
        if debt + payment < 0:
            heappush(debtors, (debt + payment, debtor))
        if credit + payment < 0:
            heappush(creditors, (credit + payment, creditor))
    return transfers
import json
import sys

from .core import balances, settle
from .errors import ValidationError
from .money import format_money, parse_integer


_NAME_ESCAPES = {
    ord(char): ascii(char)[1:-1]
    for char in "\\" + "\n\r\v\f\x1c\x1d\x1e\x85\u2028\u2029"
}


def _ignore_non_integer(_value):
    # No ledger field accepts JSON numbers with a fraction or exponent.
    return None


def _reject_constant(value):
    raise ValueError(f"invalid JSON constant {value}")


def _format_name(name):
    # Keep each record on one line and render escaped JSON surrogates safely.
    name = name.translate(_NAME_ESCAPES)
    return name.encode("utf-8", errors="backslashreplace").decode("utf-8")


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 2:
        print("usage: python3 -m ledger {balances,settle} GROUP.json", file=sys.stderr)
        return 1
    command, path = argv
    if command not in ("balances", "settle"):
        print(f"unknown command {command!r}", file=sys.stderr)
        return 1

    try:
        with open(path, "rb") as file:
            data = file.read()
        # Detect the JSON encoding, then decode strictly before parsing escapes.
        group = json.loads(
            data.decode(json.detect_encoding(data)),
            parse_int=parse_integer,
            parse_float=_ignore_non_integer,
            parse_constant=_reject_constant,
        )
    except (OSError, ValueError, RecursionError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1

    try:
        if command == "balances":
            for name, cents in sorted(balances(group).items()):
                print(f"{_format_name(name)}: {format_money(cents, signed=True)}")
        else:
            transfers = settle(group)
            if not transfers:
                print("all settled")
            for sender, recipient, cents in transfers:
                print(f"{_format_name(sender)} -> {_format_name(recipient)}: {format_money(cents)}")
    except ValidationError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    return 0
